p=ROOT/'config/concepts.json';d=json.loads(p.read_text());snap=ROOT/'snapshots/config_before_S7_045_concept.json';assert not snap.exists();snap.write_bytes(p.read_bytes());ids={c['id'] for c in d['concepts']}
